// Test a degree-3 root in ANY 26-vertex, 75-edge triangle-free H with alpha<=7.
// rustc -O; argv[1] is the complete r37_22.g6 catalogue.
use std::{env,fs,collections::BTreeMap};
fn sets(a:&[u32],mut pool:u32,k:u32,mask:u32,out:&mut Vec<u32>){if k==0{out.push(mask);return}while pool.count_ones()>=k{let v=pool.trailing_zeros()as usize;pool&=pool-1;sets(a,pool&!a[v],k-1,mask|(1<<v),out)}}
fn dis(a:&[u64],b:&[u64])->bool{!a.iter().zip(b).any(|(&x,&y)|x&y!=0)}
fn count(line:&[u8])->(u32,u64,u64){assert_eq!(line[0],85);let mut a=[0u32;22];let mut k=0;for j in 0..22{for i in 0..j{if (line[1+k/6]-63)>>(5-k%6)&1!=0{a[i]|=1<<j;a[j]|=1<<i}k+=1}}let e=a.iter().map(|s|s.count_ones()).sum::<u32>()/2;let budget=72-e;let full=(1<<22)-1;let mut six=vec![];let mut five=vec![];sets(&a,full,6,0,&mut six);sets(&a,full,5,0,&mut five);let mut libs=[vec![],vec![],vec![],vec![],vec![],vec![],vec![]];for s in 2..=6{sets(&a,full,s,0,&mut libs[s as usize])}let s:Vec<u32>=libs.iter().flatten().copied().collect();let siz:Vec<_>=s.iter().map(|v|v.count_ones()).collect();let miss:Vec<_>=s.iter().map(|&u|{let mut m=vec![0u64;(six.len()+63)/64];for(i,&v)in six.iter().enumerate(){if u&v==0{m[i/64]|=1<<(i%64)}}m}).collect();let mut first=0;let mut triples=0;
for i in 0..s.len(){if 3*siz[i]>budget{break}for j in i..s.len(){if siz[i]+2*siz[j]>budget{break}let z=budget-siz[i]-siz[j];if z>6||!dis(&miss[i],&miss[j]){continue}first+=1;let start=siz.partition_point(|&x|x<z).max(j);let end=siz.partition_point(|&x|x<=z);for h in start..end{if !dis(&miss[i],&miss[h])||!dis(&miss[j],&miss[h]){continue}let u=s[i]|s[j]|s[h];if five.iter().any(|m|m&u==0){continue}if (0..22).any(|v|{let d=a[v].count_ones()+((s[i]>>v)&1)+((s[j]>>v)&1)+((s[h]>>v)&1);!(3..=7).contains(&d)}){continue}triples+=1;eprintln!("{} {} {} {}",std::str::from_utf8(line).unwrap(),s[i],s[j],s[h]);}}}
(e,first,triples)}
fn main(){let text=fs::read_to_string(env::args().nth(1).unwrap()).unwrap();let mut table=BTreeMap::new();for l in text.lines(){let(e,p,t)=count(l.as_bytes());let v=table.entry(e).or_insert([0,0,0,0]);v[0]+=1;v[1]+=p;v[2]+=t;v[3]+=u64::from(t!=0)}println!("edges records candidate_small_pairs valid_triples productive_records");for(e,[n,p,t,k])in table{println!("{e} {n} {p} {t} {k}")}}
